<section class="page-heading small-heading"><div class="site-width"><span class="section-label">HALDUS</span><h1>Õppematerjalid</h1><p>Lisa, muuda ja kustuta portaali õppematerjale.</p></div></section><section class="site-width section"><div class="manage-actions"><a class="btn btn-primary" href="<?= e(url('admin/edit')) ?>">+ Lisa õppematerjal</a><a class="text-link" href="<?= e(url('admin/')) ?>">← Tagasi haldusesse</a></div><?php if ($notice=flash()): ?><div class="alert alert-success" role="status"><?= e($notice) ?></div><?php endif; ?><div class="table-scroll"><table class="admin-table"><thead><tr><th>Õppematerjal</th><th>Õppeaine</th><th>Staatus</th><th>Tegevused</th></tr></thead><tbody><?php foreach ($lessons as $lesson): ?><tr><td><strong><?= e($lesson['title']) ?></strong><small><?= e($lesson['level']) ?> · <?= (int)$lesson['duration_min'] ?> min</small></td><td><?= e($lesson['subject_name']) ?></td><td><span class="status-pill <?= $lesson['published']?'status-live':'status-draft' ?>"><?= $lesson['published']?'Avaldatud':'Mustand' ?></span></td><td><div class="table-actions"><a class="text-link" href="<?= e(url('admin/edit?id='.$lesson['id'])) ?>">Muuda</a><a class="text-link" href="<?= e(url('admin/quiz?lesson_id='.$lesson['id'])) ?>">Test</a><form method="post" action="<?= e(url('admin/delete')) ?>" onsubmit="return confirm('Kas kustutada see õppematerjal ja selle testid ning kommentaarid?');"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$lesson['id'] ?>"><button class="delete-link" type="submit">Kustuta</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$lessons): ?><div class="empty-state">Õppematerjale veel ei ole.</div><?php endif; ?></section>
